using System;
using System.Linq;
using System.Collections.Generic;
using NUnit.Framework;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using SporeGobbo.Geometry.Preview.Editor;
namespace SporeGobbo.Geometry.Preview.Tests
{
 public sealed class Stage55Tests
 {
  sealed class Open:IStreamingTerrainDefinition{public bool Protected(int x,int y)=>false;public bool TrySolid(int x,int y,out bool solid){solid=false;return true;}}
  static FocusProjection Map(double x=512,double y=512)=>new FocusProjection(new Point2(x,y),52,28,30,.55,.12,1.9,new Point2(0,5.89),false,45,24,12.5,.75);
  [Test]public void PaletteV2All29ExactNamedValues(){string[] names={"InkBlack","VoidBlackGreen","PermanentMossBlack","PermanentWallFace","PermanentDeepShadow","UndugDirtMass","UndugDirtVariation","FreshFractureEdge","DigWallUpper","DigWallLower","WallFootOcclusion","FloorSlateBlue","FloorDust","FloorDeepBlueShadow","FloorPlumShadow","StoneLight","StoneBase","StoneShadow","StoneDeep","RootLight","RootBase","RootShadow","BoneLimestone","BoneShadow","MossStain","SicklyLichen","DeepCerulean","CeruleanGlow","BlueViolet"};string[] hex={"050907","08120F","111B17","1B2722","0C1411","242A26","30322F","676255","504D46","282F2B","151A19","465963","566469","172735","453B51","697476","465156","293338","171D20","604A3D","49362F","241B1B","C8C1AA","817D70","536047","7E904B","176B8B","35A4C5","51445F"};var p=ScriptableObject.CreateInstance<Stage55Palette>();try{Assert.That(p.entries.Select(e=>e.name),Is.EqualTo(names));for(int i=0;i<names.Length;i++)Assert.That(ColorUtility.ToHtmlStringRGB(p.Color(names[i])),Is.EqualTo(hex[i]));Assert.That(p.Matter(PreviewMatter.Root),Is.EqualTo("RootBase"));Assert.That(p.Matter(PreviewMatter.Stone),Is.EqualTo("StoneBase"));Assert.That(p.Matter(PreviewMatter.Bone),Is.EqualTo("BoneLimestone"));}finally{UnityEngine.Object.DestroyImmediate(p);}}
  [Test]public void ZeroHeightIsExactlyTerrainAndHeightDoesNotSampleNorth(){foreach(double y in new[]{450d,490,512,550}){var m=Map();var g=new Point2(518,y);Assert.That(ElevatedProjection.Project(m,new ElevatedVertex(g,0)),Is.EqualTo(m.Project(g)));var p=ElevatedProjection.Project(m,new ElevatedVertex(g,30));Assert.That(p.X,Is.EqualTo(m.Project(g).X));Assert.That(m.Project(g).Y-p.Y,Is.EqualTo(30*Math.Sqrt(m.ScaleX(g.X)*m.ScaleY(g.Y))).Within(1e-10));}}
  [Test]public void MovingCameraPreservesGroundAttachmentAndHasExpectedScaleParallax(){var v=new ElevatedVertex(new Point2(530,485),32);foreach(int d in Enumerable.Range(-40,81)){var m=Map(512+d*.25,512+d);var baseP=ElevatedProjection.Project(m,new ElevatedVertex(v.Ground,0));Assert.That(baseP,Is.EqualTo(m.Project(v.Ground)));var top=ElevatedProjection.Project(m,v);Assert.That(top.Y,Is.LessThan(baseP.Y));Assert.That(top.X,Is.EqualTo(baseP.X));}}
  [Test]public void ActualGpuElevationMatchesCpuAcrossCameraMotion(){var shader=AssetDatabase.LoadAssetAtPath<ComputeShader>("Assets/Terrain/Geometry/Preview/Runtime/Stage55Elevation.compute");Assert.That(shader,Is.Not.Null);double worst=0;var input=new Vector4[256];for(int i=0;i<input.Length;i++)input[i]=new Vector4(450+(i*17)%160,430+(i*31)%180,i%43,0);foreach(int camera in new[]{-40,0,40})foreach(int originValue in new[]{0,512}){var origin=new Point2(originValue,originValue);var m=Map(512,512+camera);ProjectionShaderContract.Apply(m,new Stage4Settings(),true,shader,origin);using(var a=new ComputeBuffer(input.Length,16))using(var b=new ComputeBuffer(input.Length,8)){var local=input.Select(v=>new Vector4(v.x-originValue,v.y-originValue,v.z,v.w)).ToArray();a.SetData(local);int k=shader.FindKernel("Evaluate");shader.SetInt("Count",input.Length);shader.SetBuffer(k,"Input",a);shader.SetBuffer(k,"Output",b);shader.Dispatch(k,4,1,1);var output=new Vector2[input.Length];b.GetData(output);for(int i=0;i<input.Length;i++){var p=ElevatedProjection.Project(m,new ElevatedVertex(new Point2(input[i].x,input[i].y),input[i].z));worst=Math.Max(worst,Math.Max(Math.Abs(p.X-output[i].x),Math.Abs(p.Y-output[i].y)));}}}TestContext.WriteLine("GPU worst logical display units "+worst);Assert.That(worst,Is.LessThan(.00015));}
  [TestCase(LandmarkProfile.SmoothReference)][TestCase(LandmarkProfile.BroadShoulder)][TestCase(LandmarkProfile.Segmented)][TestCase(LandmarkProfile.Cluster)]public void FourSilhouettesDeterministicFiniteAndGrounded(LandmarkProfile profile){var a=ElevatedShapes.Spike(new Point2(20,30),7,32,profile);var b=ElevatedShapes.Spike(new Point2(20,30),7,32,profile);Assert.That(a.Sections[0].Left.Height,Is.Zero);Assert.That(a.Sections.Last().Left.Height,Is.EqualTo(32));Assert.That(a.Sections.Select(s=>s.Left.Ground),Is.EqualTo(b.Sections.Select(s=>s.Left.Ground)));Assert.That(a.Sections.All(s=>s.Right.Ground.X>=s.Left.Ground.X));}
  [Test]public void RootJunctionsShareExactGroundAndHeightAcrossBranches(){var roots=ElevatedShapes.Roots(new ExplorationFixture());Assert.That(roots[0].Sections.Last().Left.Ground,Is.EqualTo(roots[1].Sections[0].Left.Ground));Assert.That(roots[1].Sections[8].Left.Ground,Is.EqualTo(roots[2].Sections[0].Left.Ground));Assert.That(roots[1].Sections[8].Left.Height,Is.EqualTo(roots[2].Sections[0].Left.Height));Assert.That(roots[2].Sections.Select(s=>s.Left.Ground.Y).Distinct().Count(),Is.GreaterThan(2));Assert.That(roots[1].Sections.Max(s=>s.Left.Height),Is.GreaterThan(roots[0].Sections.Max(s=>s.Left.Height)));}
  [TestCase(false)][TestCase(true)]public void MeshBoundsContainEveryProjectedElevatedVertexWithoutCameraReassembly(bool legacy){var p=ScriptableObject.CreateInstance<Stage55Palette>();using(var e=new ExplorationExperiment()){var d=new ElevatedMesh();d.Build(ElevatedShapes.Roots(e.Fixture)[1],p,PreviewMatter.Root,e.World,e.Fixture.Landmarks[1]);var before=d.Vertices.ToArray();foreach(int camera in new[]{-80,0,80}){var m=Map(512,512+camera);var box=d.Bounds(m,legacy);foreach(var v in d.Vertices){var q=legacy?ElevatedProjection.Legacy(m,v):ElevatedProjection.Project(m,v);Assert.That(q.X,Is.InRange(box.Min.X,box.Max.X));Assert.That(q.Y,Is.InRange(box.Min.Y,box.Max.Y));}}Assert.That(d.Vertices,Is.EqualTo(before));Assert.That(e.World.Revision,Is.Zero);}UnityEngine.Object.DestroyImmediate(p);}
  [Test]public void LowRootBurialClipsCanonicalTerrainAndDoesNotMutateImmutableSource(){var p=ScriptableObject.CreateInstance<Stage55Palette>();using(var e=new ExplorationExperiment()){var path=ElevatedShapes.Roots(e.Fixture)[3];var before=path.Sections.Select(s=>s.Left.Ground).ToArray();var a=new ElevatedMesh();a.Build(path,p,PreviewMatter.Root,e.World,e.Fixture.Landmarks[1]);int n=a.Indices.Count;for(int y=-21;y<=-10;y++)for(int x=15;x<=29;x++)e.World.Excavate(e.Fixture.X+x,e.Fixture.Y+y);var b=new ElevatedMesh();b.Build(path,p,PreviewMatter.Root,e.World,e.Fixture.Landmarks[1]);Assert.That(b.Indices.Count,Is.GreaterThan(0));Assert.That(path.Sections.Select(s=>s.Left.Ground),Is.EqualTo(before));Assert.That(e.Fixture.Landmarks[1].Footprint.All(c=>e.World.IsSolid(c.X,c.Y)));}UnityEngine.Object.DestroyImmediate(p);}
  [Test]public void CoherentConnectedRootPresentationCannotRevealHiddenFloor(){using(var e=new ExplorationExperiment()){var before=e.Discovery.Remembered.ToArray();var roots=ElevatedShapes.Roots(e.Fixture);foreach(var r in roots)foreach(var section in r.Sections)ElevatedProjection.Project(Map(),section.Left);Assert.That(e.Discovery.Remembered.SetEquals(before));Assert.That(e.Discovery.Known(e.Fixture.X+149,e.Fixture.Y-8),Is.False);}}
  [Test]public void ChamberTimeBoundAndNearbyUrgencyDoNotDependOnRoomArea(){foreach(int radius in new[]{5,15}){var w=new StreamingWorld(64,64,47045,new Open());var cells=new List<int>();for(int y=32-radius;y<=32+radius;y++)for(int x=32-radius;x<=32+radius;x++)cells.Add(y*64+x);var ix=new DiscoveryIndex(w,new[]{new DiscoveryRegion("chamber",cells,DiscoveryPolicy.Gradual,.8,8)});using(var d=new CaveDiscovery(w,ix){FastChambers=true,ImmediateDistance=8,MaxReleases=32}){d.Explore(new Point2(32.5,32.5));d.Tick(0);Assert.That(d.Shown(32,36));for(int n=0;n<24;n++)d.Tick(1.0/60);Assert.That(cells.All(i=>d.Shown(i%64,i/64)));Assert.That(cells.All(i=>d.Visual.Contains(i)));}}}
  [Test]public void BoundedTunnelNeverBecomesWholeNetworkOnFastChamberSetting(){using(var e=new ExplorationExperiment()){e.Discovery.FastChambers=true;e.Discovery.Explore(e.Fixture.P(90,-21));e.Discovery.Tick(1);Assert.That(e.Discovery.Known(e.Fixture.X+149,e.Fixture.Y-8),Is.False);Assert.That(e.World.Revision,Is.Zero);}}
  [Test]public void ConcealedThreatCannotBeginOrCompleteAttackButKeepsSimulationClock(){var w=new StreamingWorld(32,32,47045,new Open());var ix=new DiscoveryIndex(w,Array.Empty<DiscoveryRegion>());using(var d=new CaveDiscovery(w,ix)){var actor=new LabActor();actor.Reset(0,"test",new List<Point2>{new Point2(10.5,10.5)},1,true,LabAttack.ShortMelee);var player=new Point2(11.5,10.5);actor.AttackReadable=(a,p)=>EncounterReadability.Allowed(d,a,p,2);actor.State=LabState.Pursuing;var tuning=new LabTuning();for(int i=0;i<120;i++)actor.Step(1.0/60,player,tuning,w);Assert.That(actor.Attacks,Is.Zero);Assert.That(actor.Clock,Is.GreaterThan(1));Assert.That(actor.State,Is.Not.EqualTo(LabState.Telegraphing));d.SeedKnown(ix.Regions.SelectMany(r=>r.Cells));for(int i=0;i<150;i++)actor.Step(1.0/60,player,tuning,w);Assert.That(actor.Attacks,Is.GreaterThan(0));}}
  [Test]public void AttackGateRequiresTelegraphCellsAndNeverUsesCamera(){var w=new StreamingWorld(32,32,47045,new Open());var ix=new DiscoveryIndex(w,Array.Empty<DiscoveryRegion>());using(var d=new CaveDiscovery(w,ix)){var a=new LabActor();a.Reset(0,"test",new List<Point2>{new Point2(10.5,10.5)},1,true,LabAttack.ShortMelee);var player=new Point2(11.5,10.5);d.SeedKnown(new[]{10*32+10,10*32+11});Assert.That(EncounterReadability.Allowed(d,a,player,5),Is.False);d.SeedKnown(Enumerable.Range(10,7).Select(x=>10*32+x));Assert.That(EncounterReadability.Allowed(d,a,player,5));}}
  [Test]public void CachedClippingExactlyMatchesFrozenCanonicalReferenceBeforeAndAfterExcavation(){var palette=ScriptableObject.CreateInstance<Stage55Palette>();try{using(var e=new ExplorationExperiment()){for(int pass=0;pass<2;pass++){if(pass==1)for(int y=-21;y<=-10;y++)for(int x=15;x<=29;x++)e.World.Excavate(e.Fixture.X+x,e.Fixture.Y+y);foreach(var path in ElevatedShapes.Roots(e.Fixture)){var actual=new ElevatedMesh();var reference=new Stage55ClippingReference();actual.Build(path,palette,PreviewMatter.Root,e.World,e.Fixture.Landmarks[1]);reference.Build(path,palette,PreviewMatter.Root,e.World,e.Fixture.Landmarks[1]);Assert.That(actual.Indices,Is.EqualTo(reference.Indices));Assert.That(actual.Colors,Is.EqualTo(reference.Colors));Assert.That(actual.Vertices.Count,Is.EqualTo(reference.Vertices.Count));for(int i=0;i<actual.Vertices.Count;i++){Assert.That(actual.Vertices[i].Ground,Is.EqualTo(reference.Vertices[i].Ground));Assert.That(actual.Vertices[i].Height,Is.EqualTo(reference.Vertices[i].Height));}}}}}finally{UnityEngine.Object.DestroyImmediate(palette);}}
  [Test]public void NewSceneOwnsBoundedResourcesAndCleanupPreservesOldPreview(){Stage55Tools.Install();var e=UnityEngine.Object.FindAnyObjectByType<Stage55Preview>();e.Initialize();Assert.That(e.GetComponent<Stage54Preview>(),Is.Null);for(int i=0;i<3;i++){e.ResetDemo();Assert.That(e.ElevatedOwnedMeshes,Is.EqualTo(6));Assert.That(e.OwnedMeshes,Is.EqualTo(5));}var meshes=e.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Stage55 ")).Select(f=>f.sharedMesh).ToArray();e.Shutdown();Assert.That(meshes.All(m=>m==null));EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);}
 }
}
